#define GPIO_BASE_PHYS_ADDR         0x20180000000
#define MEM_BASE_PHYS_ADDR          0x30000000

#define PROG_OFFSET                 0x000000

#define BUFFER_SIZE                 0x100000
#define BUFFER_NUM                  0x4

#define PROG_ADDR_OFFSET            0x0
#define RST_OFFSET                  0x4
#define FLUSH_OFFSET                0x8

#define RVFI_START_ADDR             0x100000
#define CSR_START_ADDR              0x400000
#define DSIDE_START_ADDR            0x400000

#define RVFI_HW_IDX_OFFSET          0x10
#define RVFI_BASE_ADDR_OFFSET       0x14
#define RVFI_SW_IDX_OFFSET          0xC

#define CSR_HW_IDX_OFFSET           0x1C
#define CSR_BASE_ADDR_OFFSET        0x20
#define CSR_SW_IDX_OFFSET           0x18

#define DSIDE_HW_IDX_OFFSET         0x28
#define DSIDE_BASE_ADDR_OFFSET      0x2C
#define DSIDE_SW_IDX_OFFSET         0x24

// when write pointer reaches end of a buffer, hw_idx is incremented
// when  read pointer reaches end of a buffer, sw_idx is incremented
// let n be the number of buffers
// hw: I can write as long as I am not writing over somthing not read
//     so when incrementing hw_idx, if hw_idx + 1 == sw_idx + n, I stop
// sw: I can read as long as I am not going ahead of hw_idx
//     so when incrementing sw_idx, if sw_idx + 1 == hw_idx,     I stop
// need > 2 buffers for this to work

uint32_t MEM_VIRT_ADDR = 0;
uint32_t GPIO_VIRT_ADDR = 0;

typedef uint32_t bits_t;

struct mem_ptr_t {

  uint64_t phys_addr;

  mem_ptr_t (uint32_t of) : phys_addr(MEM_BASE_PHYS_ADDR + of) {}

  uint32_t in() {
    return *(volatile uint32_t*)(MEM_VIRT_ADDR + phys_addr);
  }

  void out(uint32_t val) {
    *(volatile uint32_t*)(MEM_VIRT_ADDR + phys_addr) = val;
  }

  void inc() {
    phys_addr += 4;
  }

  uint32_t get_abs() const {
    return phys_addr;
  }

  bool operator>=(const mem_ptr_t &other) const {
    return phys_addr >= other.phys_addr;
  }

  mem_ptr_t operator+(const uint32_t add) {
    mem_ptr_t x(add);
    x.phys_addr = this->phys_addr + add;
    return x;
  }
};

struct gpio_ptr_t {

  uint64_t phys_addr;

  gpio_ptr_t (uint32_t of) : phys_addr(GPIO_BASE_PHYS_ADDR + of) {}

  uint32_t in() {
    return *(volatile uint32_t*)(GPIO_VIRT_ADDR + phys_addr);
  }

  void out(uint32_t val) {
    *(volatile uint32_t*)(GPIO_VIRT_ADDR + phys_addr) = val;
  }

  void out(mem_ptr_t addr) {
    *(volatile uint32_t*)(GPIO_VIRT_ADDR + phys_addr) = addr.phys_addr;
  }

  gpio_ptr_t& operator=(const uint32_t of) {
    phys_addr = of;
    return *this;
  }
};

template<typename T, uint32_t L>
struct stream_ctrl {


  mem_ptr_t base_addr;

  uint32_t  last_hw_idx; 
  uint32_t  sw_idx;

  gpio_ptr_t sw_idx_ptr;
  gpio_ptr_t hw_idx_ptr;
  gpio_ptr_t base_addr_ptr;

  uint32_t data [L];
  uint32_t data_idx;

  stream_ctrl (uint32_t sip, uint32_t hip, uint32_t bap, uint32_t sa) :
    base_addr(sa),
    last_hw_idx(0),
    sw_idx(0),
    sw_idx_ptr(sip),
    hw_idx_ptr(hip),
    base_addr_ptr(bap),
    data_idx(0)
  { }

  void set_addrs() {
    base_addr_ptr.out(base_addr.get_abs());
    sw_idx_ptr.out(sw_idx);
  }

  bool in32(uint32_t &res) {
    auto next_sw_idx = (sw_idx + 4 == BUFFER_SIZE) ? 0 : sw_idx + 4;
    if (next_sw_idx == last_hw_idx) {
      last_hw_idx = hw_idx_ptr.in();
      if (next_sw_idx == last_hw_idx) {
	return false;
      }
    }
    res = (base_addr + sw_idx).in();
    sw_idx = next_sw_idx;
    sw_idx_ptr.out(sw_idx);
    return true;
  }

  T* read() {
    while (data_idx < L) {
      if (!in32(data[data_idx])) {
	return nullptr;
      }
      data_idx ++;
    }
    data_idx = 0;
    return reinterpret_cast<T*>(data);
  }
  
};

struct ps_io_ctrl {

  static constexpr int rst_bit = 1;
  static constexpr int flush_bit = 0;

  gpio_ptr_t rst_ptr;

  mem_ptr_t prog_base_addr;
  gpio_ptr_t prog_base_addr_ptr;

  stream_ctrl<char, 8> rvfi_stream;
  stream_ctrl<char, 2> csr_stream;
  stream_ctrl<char, 4> dside_stream;
  // rvfi* curr_rvfi;
  // csr* curr_csr;

  ps_io_ctrl() :
    rst_ptr(RST_OFFSET),
    prog_base_addr(PROG_OFFSET),
    prog_base_addr_ptr(PROG_ADDR_OFFSET),
    rvfi_stream(RVFI_SW_IDX_OFFSET,
                RVFI_HW_IDX_OFFSET,
                RVFI_BASE_ADDR_OFFSET,
                RVFI_START_ADDR),
    csr_stream(CSR_SW_IDX_OFFSET, 
               CSR_HW_IDX_OFFSET,
               CSR_BASE_ADDR_OFFSET,
               CSR_START_ADDR),
    dside_stream(DSIDE_SW_IDX_OFFSET, 
		 DSIDE_HW_IDX_OFFSET,
		 DSIDE_BASE_ADDR_OFFSET,
		 DSIDE_START_ADDR)
    { }
  
  void start(uint32_t * prog_data, uint32_t size) {
    rst_ptr.out(0);
    mem_ptr_t curr_prog_addr = prog_base_addr;
    for (uint32_t i = 0; i < size; i ++) {
      curr_prog_addr.out(prog_data[i]);
      curr_prog_addr.inc();
    }
    uint64_t v = prog_base_addr.get_abs();
    prog_base_addr_ptr.out(prog_base_addr.get_abs());
    Xil_DCacheFlushRange(prog_base_addr.get_abs(), 8192);
    Xil_DCacheFlushRange(RVFI_START_ADDR, 131072);
    Xil_DCacheFlushRange(CSR_START_ADDR, 131072);
    Xil_DCacheFlushRange(DSIDE_START_ADDR, 131072);
    rvfi_stream.set_addrs();
    csr_stream.set_addrs();
    dside_stream.set_addrs();
    rst_ptr.out(1);
  }
  
  void run() {
    sleep(1);
    Xil_DCacheFlushRange(RVFI_START_ADDR, 131072);
    Xil_DCacheFlushRange(CSR_START_ADDR, 131072);
    Xil_DCacheFlushRange(DSIDE_START_ADDR, 131072);
  }
};
void run() {
    ps_io_ctrl ctrl;
    ctrl.start(PROG, PROG_LEN);
    ctrl.run();
}
